const body = $json.body || {};
if (!body.contractAddress || !body.drainAmountWei || !body.txHash) {
  throw new Error('Invalid Payload: Missing fields');
}
const drainWei = BigInt(body.drainAmountWei);
const thresholdWei = BigInt('5000000000000000000');
const severity = drainWei >= thresholdWei ? 'CRITICAL' : 'HIGH';
return [{
  json: {
    incidentId: $execution.id,
    contractAddress: body.contractAddress.toLowerCase(),
    txHash: body.txHash,
    drainAmountWei: body.drainAmountWei,
    severity: severity,
    timestamp: Date.now()
  }
}];
